const R10=window.REFERENCE_NETWORK;
const V10={view:'asof',match:null,report:null,sections:[],weatherStatus:'',exportLabel:''};
const v10ResolveBase=vResolve;
function v10Normalize(s){return String(s||'').trim().replace(/^广东省/,'').replace(/^深圳市?/,'').replace(/^罗湖区/,'').replace(/地铁站$/,'').replace(/站$/,'')}
vResolve=function(text){const old=v10ResolveBase(text);if(old)return old;const n=v10Normalize(text);let p=R10.stations.find(x=>x.name===n)||R10.places.find(x=>v10Normalize(x.name)===n);if(!p&&!n.endsWith('街道'))p=R10.places.find(x=>x.name===n+'街道');if(p)return {...p,name:p.name,origin:'本地OSM参考位置',regionOnly:['suburb','neighbourhood','quarter','locality'].includes(p.kind),coordinate_basis:p.coordinate_basis||'站点公开坐标，入口需核验'};if(String(text).trim()==='罗湖区')return {name:'罗湖区',lat:22.555341,lon:114.123885,regionOnly:true,origin:'区级代表位置，非具体地址'};const street=D.risks.find(r=>r.street===n||r.street===n+'街道');if(street)return {name:street.street,regionOnly:true,lat:null,lon:null,origin:'已匹配街道资料，坐标尚未取得'};return null};
function v10Distance(a,b){if(!a||!b||![a.lat,a.lon,b.lat,b.lon].every(Number.isFinite))return null;return Math.hypot((a.lon-b.lon)*Math.cos((a.lat+b.lat)*Math.PI/360),a.lat-b.lat)*111320}
function v10Time(){return V2.mode==='history'?V2.at:dateText(new Date().toISOString())}
const v10TimeControlsBase=vTimeControls;
vTimeControls=function(){const historical=V9.active;return `<div class="v4time"><div class="v10nowbox"><small>真实现在时刻（自动更新，不可编辑）</small><b id="v10-current-clock" data-live-clock>${esc(typeof v17NowText==='function'?v17NowText():dateText(new Date().toISOString()))}</b></div>${historical?`<label class="v10nowlabel">历史模拟时刻 · 不在行程中修改</label><b class="v10now">${esc(dateText(V2.at))}</b><small>在页面上方历史时间栏切换时刻</small>`:''}<div class="chips" style="margin-top:10px"><button data-v2="departure" data-value="immediate" class="${V2.departure==='immediate'?'active':''}">${historical?'按模拟时刻出发':'现在出发'}</button><button data-v2="departure" data-value="planned" class="${V2.departure==='planned'?'active':''}">计划出发</button></div>${V2.departure==='planned'?`<div class="field"><label>预计出发时间${historical?'（不改变资料截止时刻）':''}</label><input id="v2-planned" type="datetime-local" value="${V2.planned}"></div>`:''}</div>`};
v9Banner=function(){return ''};
function v10WeatherMatch(){const p=vResolve(V5.weatherPlace);return `<div class="v10coverage ${p?'':'unmatched'}"><b>${p?'匹配结果：'+esc(p.name):'地点尚未匹配：'+esc(V5.weatherPlace)}</b><p>${p?(p.regionOnly?'这是区域查询，不能作为小区入口坐标。':esc(p.coordinate_basis||'站点或输入坐标，未经实地核验。')):'本地索引覆盖已收集站点、街道及部分医院／学校。可输入纬度,经度，或在地图上选点。'}</p><small>${V2.mode==='history'?'历史报道雨量有指定站点与统计时段；未取得此地点观测时不套用别处雨量。':'有坐标时查询该代表点模型天气；模型数据不是本地站点实测。'}</small>${V10.weatherStatus?'<p>'+esc(V10.weatherStatus)+'</p>':''}</div>`}
const v10WeatherBase=v8Weather;v8Weather=function(){let h=v10WeatherBase();if(!h.includes('id="v5-weather-place"'))h=`<div class="v5weatherplace"><label>天气地点 <input id="v5-weather-place" value="${esc(V5.weatherPlace)}" placeholder="输入街道、小区或坐标"></label><button data-v5="weather">查询匹配与覆盖</button></div>`+h;return h+v10WeatherMatch()};
const v10FetchWeatherBase=vFetchWeather;
vFetchWeather=async function(){vDraft();const field=document.getElementById('v5-weather-place');if(field)V5.weatherPlace=field.value.trim();const p=vResolve(V5.weatherPlace);V10.weatherStatus='';if(!p){V2.weather=null;V10.weatherStatus='无法定位：请输入本地已收集地点或坐标。';vRender();return}if(V9.active){V10.weatherStatus='已按历史时刻读取归档资料；该地点的连续实测雨量尚未取得。';vRender();return}if(!Number.isFinite(p.lat)||!Number.isFinite(p.lon)){V2.weather=null;V10.weatherStatus='已匹配街道名称，坐标缺失，未向天气服务发送错误位置。';vRender();return}return v10FetchWeatherBase()};
function v10MetroPath(a,b){const queue=[[a,[]]],seen=new Set([a]);while(queue.length){const [node,path]=queue.shift();if(node===b)return path;for(const e of R10.edges){const to=e.from===node?e.to:e.to===node?e.from:null;if(to&&!seen.has(to)){seen.add(to);queue.push([to,[...path,{...e,reversed:e.to===node}]])}}}return null}
function v10Nearest(p){if(!p||!Number.isFinite(p.lat))return null;return R10.stations.map(s=>({...s,accessDistance:v10Distance(p,s)})).filter(s=>s.accessDistance!=null&&s.accessDistance<=1200).sort((a,b)=>a.accessDistance-b.accessDistance)[0]||null}
function v10LineStop(line){if(V2.mode!=='history'||!V2.at.startsWith('2023-09-08'))return null;const id={'1':'SZ-E006','2':'SZ-E013','5':'SZ-E007','3':'SZ-E014'}[line];return vEvents().find(e=>e.record_id===id)||null}
function v10TransitPlan(plan,coords){const stations=coords.map(c=>R10.stations.find(s=>s.name===c?.name)||v10Nearest(c));if(stations.some(x=>!x))return {...plan,label:'地铁接驳范围未覆盖，无法生成方案',duration:null,geometry:null,segments:[]};const edges=[];for(let i=1;i<stations.length;i++){const path=v10MetroPath(stations[i-1].name,stations[i].name);if(!path)return {...plan,label:'本地参考走廊未连接，未生成虚构地铁方案',duration:null,geometry:null,segments:[]};edges.push(...path)}const groups=[];for(const e of edges){const from=e.reversed?e.to:e.from,to=e.reversed?e.from:e.to,geo=e.reversed?[...e.geometry.coordinates].reverse():e.geometry.coordinates,prev=groups.at(-1);if(prev?.line===e.line&&prev.to===from){prev.to=to;prev.stops+=e.stopCount||1;prev.viaStops.push(...(e.viaStops||[]),to);prev.coordinates.push(...geo.slice(1));}else groups.push({type:'metro',line:e.line,from,to,stops:e.stopCount||1,viaStops:[...(e.viaStops||[]),to],coordinates:[...geo],source:'当前OSM轨道参考；线路结构仅含2023已有走廊'});}for(const g of groups){g.closure=v10LineStop(g.line);g.closed=!!g.closure}const blocked=groups.some(g=>g.closed),walkMeters=(v10Distance(coords[0],stations[0])||0)+(v10Distance(coords.at(-1),stations.at(-1))||0),baseMinutes=edges.reduce((n,e)=>n+(e.stopCount||1),0)*2.5+Math.max(0,groups.length-1)*5+walkMeters/80,range=[Math.ceil(baseMinutes+3),Math.ceil(baseMinutes+8)],depart=plan.planned||(V2.mode==='history'?V2.at:businessNow().toISOString());const start=new Date(depart.endsWith('Z')?depart:depart+':00+08:00');return {...plan,geometry:{type:'LineString',coordinates:groups.flatMap(g=>g.coordinates)},geometryBasis:'current-reference',duration:blocked?null:Math.ceil((range[0]+range[1])/2)*60,distance:edges.reduce((s,e)=>s+e.distance,0),segments:groups,boarding:stations[0].name,alighting:stations.at(-1).name,walkMeters,blocked,referenceMinutes:range,arrivalText:blocked?'公告涉及停运，无法计算有效到达时刻':dateText(new Date(start.getTime()+range[0]*60000).toISOString())+'—'+dateText(new Date(start.getTime()+range[1]*60000).toISOString()),label:blocked?'地铁参考方案 · 当时公告涉及停运，不可作为可乘坐方案':'地铁参考方案 · 时长为规则估算，非实际班次',estimateBasis:'每站2.5分钟、换乘5分钟、步行80m/min、等候3–8分钟估算；接驳距离为直线参考，步行路径及灾时延误未取得。'}}
const v10AddBase=vAddPlan;
vAddPlan=async function(){vDraft();if(!V2.origin.trim()||!V2.destination.trim())return toast('请填写起点和目的地');const refs=[V2.origin,...V2.vias.filter(Boolean),V2.destination],coords=refs.map(vResolve);if(coords.some(c=>!c||!Number.isFinite(c.lat)||c.regionOnly)){V2.error='部分输入只匹配到区域或没有坐标。请在地点地图选定具体位置，再设置为起点／终点；不把街道代表点当作小区入口。';vRender();return}if(V2.transport==='步行'){V2.error='步行路由尚未接通，不再用直线冒充步行路线。请核对官方出行信息。';vRender();return}const seq=++V2.requestSeq;V2.loading=true;V2.error='';vRender();const plan={id:vId(),origin:V2.origin,destination:V2.destination,vias:V2.vias.filter(Boolean),transport:V2.transport,mode:V2.mode,at:V2.at,eventId:V2.eventId,planned:V2.departure==='planned'?V2.planned:'',created:businessNow().toISOString(),actual_created_at:new Date().toISOString(),coords,duration:null,distance:null,geometry:null,roadNames:[]};try{if(V2.departure==='planned'&&(!V2.planned||new Date(V2.planned+':00+08:00')<businessNow()))throw Error('请选择未来的计划出发时间');if(V2.transport==='公共交通'){vCommitPlan(v10TransitPlan(plan,coords));}else{const res=await fetch(`https://router.project-osrm.org/route/v1/driving/${coords.map(c=>c.lon+','+c.lat).join(';')}?alternatives=3&overview=full&geometries=geojson&steps=true`,{signal:AbortSignal.timeout(18000)});if(!res.ok)throw Error('路线服务未返回');const out=await res.json();if(out.code!=='Ok'||!out.routes?.length)throw Error('未取得道路路线');if(seq!==V2.requestSeq)return;out.routes.slice(0,3).forEach(r=>vCommitPlan({...plan,id:vId(),geometry:r.geometry,geometryBasis:'current-reference',duration:r.duration,distance:r.distance,label:V2.mode==='history'?'当前道路参考轨迹 · 非历史灾时路由与时长':'OSRM道路参考 · 不含实时洪涝与拥堵',roadNames:[...new Set((r.legs||[]).flatMap(l=>(l.steps||[]).map(s=>s.name).filter(Boolean)))]}));}}catch(e){const cached=V2.transport==='驾车'&&R10.driving_samples?.find(s=>s.from===coords[0]?.name&&s.to===coords.at(-1)?.name&&coords.length===2);if(cached&&seq===V2.requestSeq){cached.routes.slice(0,3).forEach(r=>vCommitPlan({...plan,id:vId(),geometry:r.geometry,geometryBasis:'current-reference',duration:r.duration,distance:r.distance,label:'已缓存2026-10-12道路参考，不含历史灾时路况',roadNames:[...new Set((r.legs||[]).flatMap(l=>(l.steps||[]).map(s=>s.name).filter(Boolean)))]}));V2.error='在线服务未返回，显示已标明采集日期的参考轨迹。';}else if(seq===V2.requestSeq)V2.error=e.message+'。未用直线或虚构时长填充方案。'}finally{if(seq===V2.requestSeq){V2.loading=false;vRender()}}};
function v10Assess(place){const p=vResolve(place),station=R10.stations.find(s=>s.name===p?.name),affected=R10.edges.filter(e=>e.from===station?.name||e.to===station?.name).map(e=>v10LineStop(e.line)).find(Boolean);if(affected)return {level:'red',name:'已确认服务受限',detail:'该站关联区段有当时停运公告；不等于站外每处都发生深积水。',source:affected.source_url,published:affected.source_published_at};if(station?.name==='水贝'){const e=v10LineStop('3');if(e)return {level:'red',name:'已确认服务受限',detail:'3号线福保至水贝区段有当时停运公告；站外水深未取得。',source:e.source_url,published:e.source_published_at}}const r=vRisks({origin:place,destination:place,vias:[]});if(r.length)return {level:'yellow',name:'长期隐患需关注',detail:r[0].risk_description,source:r[0].source_url,published:D.guide_dates[r[0].guide_year]||'发布日期待核实'};return {level:'gray',name:'点位状态待核验',detail:'具体点位水深、入口和通行状态未取得观测。',source:null,published:null}}
function v10DistrictImpact(){return V2.mode==='history'&&V2.at.startsWith('2023-09-08')&&vEvents().find(e=>e.record_id==='SZ-E005')}
function v10RiskLayers(map,L){const district=v10DistrictImpact();if(district&&L.geoJSON)L.geoJSON(R10.area_reference,{style:{color:'#d19c55',weight:1,dashArray:'5 5',fillColor:'#d19c55',fillOpacity:.07}}).bindTooltip('罗湖区：当日已报告多路深积水。仅为区级信息覆盖范围，不是淹没边界。').addTo(map);R10.edges.forEach(e=>{const closure=v10LineStop(e.line);if(closure)L.polyline(e.geometry.coordinates.map(c=>[c[1],c[0]]),{color:'#c95454',weight:7,opacity:.65}).bindTooltip('地铁'+e.line+'号线：公告涉及停运 · '+dateText(closure.source_published_at)).addTo(map)});R10.stations.forEach(s=>{const r=v10Assess(s.name),color={red:'#c95454',orange:'#d39a52',yellow:'#c9b263',gray:'#899ca7'}[r.level];L.circleMarker([s.lat,s.lon],{radius:7,color:'#fff',weight:2,fillColor:color,fillOpacity:1,bubblingMouseEvents:false}).bindTooltip(esc(s.name)+' · '+r.name).on('click',()=>{V5.place=s.name;V2.page='map';vRender()}).addTo(map)});}
const v10RouteMapBase=v8MountRouteMap;
v8MountRouteMap=function(){v10RouteMapBase();if(V8.map&&window.L)v10RiskLayers(V8.map,window.L)};
const v10PlaceMapBase=v6MountMap;
