const v10MapPageBase=vMapPage;
vMapPage=function(){return v10MapPageBase().replace('地点标记表示资料状态。','红色表示已确认服务受限，黄色表示长期隐患；区级报道另用橙色范围提示。').replace('<div class="maplegend">','<div class="v10maplegend"><span><i style="background:#c95454"></i>红：确认服务受限</span><span><i style="background:#d19c55"></i>橙：区域影响提示</span><span><i style="background:#c9b263"></i>黄：长期隐患关注</span><span><i style="background:#899ca7"></i>灰：暂无现场观测</span></div><details class="v10oldlegend"><summary>来源分类说明</summary><div class="maplegend">').replace('<form id="v5-place-form"','</details><form id="v5-place-form"');};
v5PlaceDetail=function(){const place=V5.place,p=vResolve(place),risk=v10Assess(place),district=v10DistrictImpact(),near=p?.lat?R10.stations.map(s=>({...s,d:v10Distance(p,s)})).filter(s=>s.d!=null&&s.d<1500).sort((a,b)=>a.d-b.d):[];return `<section class="card"><div class="row"><div><h2>${esc(p?.name||place)}</h2><small>查看时刻 ${esc(v10Time())}（北京时间）</small></div><span class="tag ${risk.level==='red'?'red':risk.level==='gray'?'gray':'orange'}">${risk.name}</span></div><div class="v10placefacts"><h3>地点本身</h3><p>${esc(risk.detail)}</p>${risk.source?`<a href="${esc(risk.source)}" target="_blank" rel="noopener">依据 · 发布 ${esc(dateText(risk.published))} ↗</a>`:''}<h3>所在区域</h3><p>${district?'官方当日公告已确认罗湖区多条道路出现较深积水，并有停工安排。具体入口水深仍需现场观测；不能把区级影响当成每一点的实测值。':'没有该时刻已核验的区级现场影响记录；长期隐患与实况分开。'}</p>${district?v9AsOfLink(district):''}<h3>周边约1.5公里</h3><div class="v10nearby">${near.map(s=>`<button data-v5="place" data-value="${s.name}"><b>${s.name}</b><small>${Math.round(s.d)}m · ${v10Assess(s.name).name}</small></button>`).join('')||'<p>未取得可用于周边距离计算的具体坐标。</p>'}</div></div><p class="muted">${esc(p?.coordinate_basis||p?.origin||'坐标未匹配')}。地图范围提示不代表洪水预测边界。</p>${p&&!p.regionOnly?`<div class="chips"><button data-v10="point-origin" data-value="${esc(place)}">设为出发点</button><button data-v10="point-destination" data-value="${esc(place)}">设为目的地</button></div>`:''}</section>`};
const v10PlanBase=v8Plan;
v8Plan=function(p,i){return v10PlanBase(p,i).replace(p.duration!=null?Math.ceil(p.duration/60)+'分钟':'时长待取得',p.duration!=null?'参考'+Math.ceil(p.duration/60)+'分钟':p.blocked?'停运影响':'时长待取得').replace('</article>',`${p.segments?.length?`<div class="v10transit"><b>上车 ${esc(p.boarding)} → 下车 ${esc(p.alighting)}</b>${p.segments.map(g=>`<div class="v10leg ${g.closed?'blocked':''}"><span>${g.line}号线 · ${g.stops}站 · 下一站方向 ${esc(g.viaStops?.[0]||g.to)}</span><b>${esc(g.from)} → ${esc(g.to)}</b><small>途经：${(g.viaStops||[g.to]).map(esc).join(' → ')}</small><small>${g.closed?'当时公告涉及停运':'所收录公告未涉及此区段停运'}</small></div>`).join('')}<p>预计到达：${esc(p.arrivalText)}</p><details><summary>参考时长与接驳说明</summary><p>${p.referenceMinutes.join('–')}分钟仅为正常条件下规则估算；${p.blocked?'当前方案停运，不能使用该估算判断到达。':''}</p><small>${esc(p.estimateBasis)} 接驳约${Math.round(p.walkMeters)}m（直线参考，非步行路径）。</small></details></div>`:''}<small class="v10basis">${esc(p.label)}；轨迹不包含灾时积水与封路。${p.mode==='history'&&p.transport==='驾车'?' 历史灾时到达时间无法确认。':''}</small></article>`)};
const v10SummaryBase=v8Summary;
v8Summary=function(){const p=vFocus(),affected=p?.segments?.filter(g=>g.closed)||[];return v10SummaryBase()+`<section class="card v10assessment"><h2>出行风险评估 · 依据与行动</h2><div class="tablewrap"><table><tr><th>对象</th><th>已知影响</th><th>依据／范围</th><th>建议</th></tr>${affected.map(g=>`<tr><td>${g.line}号线 ${g.from}—${g.to}</td><td><span class="tag red">已确认受限</span></td><td>${v9AsOfLink(g.closure)}</td><td>不能作为可乘坐方案，取消停运区段乘车安排，必要事项优先远程联系目的地。</td></tr>`).join('')}<tr><td>所在区域</td><td>${v10DistrictImpact()?'罗湖当日多路深积水报道':'没有当前现场观测'}</td><td>${v10DistrictImpact()?'区级公告，不对应全部路段':'长期隐患不能替代现场状态'}</td><td>${v10DistrictImpact()?'非必要外出按官方建议减少；驾车参考路线也不保证通行。':'此范围没有当前现场观测；已收录依据见上方。'}</td></tr><tr><td>未来时段</td><td>${V2.mode==='history'?'可查当时专业判断':'数值风险模型待接入'}</td><td>没有配对水深与校准模型</td><td>不生成危险百分比；参考时长不构成安全评分。</td></tr></table></div><small>这是规则与资料支持的风险评估，不冒充AI洪水预测。历史重建记录与当时可知输入分开。</small></section>`};
const v10SourceBase=vSourceDialog;
vSourceDialog=function(kind,val){v10SourceBase(kind,val);const dialog=$('#source-dialog');if(kind==='risk'){const r=vAvailable().find(r=>r.street===val);if(r)dialog.insertAdjacentHTML?.('beforeend',`<div class="v10attachment"><b>官方附件入口</b><p>官方发布日期：${esc(D.guide_dates[r.guide_year]||'未核实，不能以采集日期替代')}</p><a href="${esc(r.source_url)}" download target="_blank" rel="noopener">下载官方原始附件 ↗</a><button data-v10="copy-source" data-value="${esc(r.source_url)}">复制直接下载链接</button><textarea readonly aria-label="直接下载链接">${esc(r.source_url)}</textarea><small>资料采集时间2026-10-11，仅用于维护记录。</small></div>`)}};
function v10ExportDialog(record=null,label='查询报告'){vExportRecord=record;V10.exportLabel=label;vDialog('选择报告内容',`<form id="v10-export"><div class="field"><label>报告事件／标题</label><input name="event" value="${V2.mode==='history'?'2023年9月深圳暴雨 · ':''}${esc(label)}" required></div><div class="exportchoices">${EXPORT_FIELDS.map(([id,t])=>`<label><input type="checkbox" name="${id}" ${!['feedback','photos'].includes(id)?'checked':''}> ${t}</label>`).join('')}</div><div class="field"><label>格式</label><select name="format"><option value="pdf">PDF报告</option><option value="html">HTML报告</option><option value="txt">纯文本</option><option value="png">PNG信息卡</option></select></div><p class="muted">保留事件、查询时刻、资料发布时间、导出时间与深雨知路水印。地图导出含已收集OSM道路与地名背景，超出覆盖范围会标注；不代表灾时通行。</p><button class="primary">预览所选内容</button></form>`)}
function v10ReportHtml(r){return `<div class="v10reportpaper" style="width:820px;padding:38px;background:white;color:#203644;font:14px/1.8 sans-serif"><div style="border-bottom:2px solid #237f80;padding-bottom:15px"><b style="color:#237f80">深雨知路 · RAINWISE</b><h1 style="font-size:25px">${esc(r.event)}</h1><p>事件范围：${r.s.mode==='history'?'2023年9月深圳暴雨':'当前出行查询'}<br>查询／回放时刻：${esc(r.s.mode==='history'?dateText(r.s.at):dateText(r.s.created))}<br>导出时间：${esc(dateText(r.exported))}</p></div>${r.parts.map(p=>`<section style="border-bottom:1px solid #e3e9ed;padding:17px 0"><h2 style="font-size:17px;color:#237f80">${esc(p.title)}</h2><div style="white-space:pre-wrap;overflow-wrap:anywhere">${esc(p.text)}</div></section>`).join('')}${r.chosen.map?'<section><h2>路线与地图背景</h2>'+vMapSvgSnapshot(r.s)+'<p>轨迹来源与灾时可用性不同；本图不保证通行。</p></section>':''}${r.chosen.photos?stored('sy-v2-feedback').filter(f=>f.photo&&vMatchText(f.place,vTerms(r.s.plans[0]))).map(f=>`<section><img style="max-width:100%" src="${f.photo}" alt="用户选择的本地图片"><p>${esc(f.place)} · 用户提供，待核验</p></section>`).join(''):''}<p style="font-size:11px;color:#8b9ca4">深雨知路 · 事实有出处，未知不冒充安全。报告不是官方预警或通行许可。</p></div>`}
async function v10Pdf(r){if(!window.jspdf?.jsPDF||!window.html2canvas)throw Error('PDF组件未加载');const host=document.createElement('div');host.style.cssText='position:absolute;left:-10000px;top:0;';host.innerHTML=v10ReportHtml(r);document.body.appendChild(host);try{const canvas=await window.html2canvas(host.firstElementChild,{scale:1.5,backgroundColor:'#ffffff',logging:false});const pdf=new window.jspdf.jsPDF({unit:'mm',format:'a4'}),pageH=277,drawW=190,ratio=canvas.width/drawW,pagePx=Math.floor(pageH*ratio),wm=document.createElement('canvas');wm.width=700;wm.height=180;const wc=wm.getContext('2d');wc.translate(350,90);wc.rotate(-.25);wc.font='bold 55px sans-serif';wc.fillStyle='rgba(35,127,128,.09)';wc.textAlign='center';wc.fillText('深雨知路 · RAINWISE',0,15);const mark=wm.toDataURL('image/png');let n=0;for(let y=0;y<canvas.height;y+=pagePx){const slice=document.createElement('canvas');slice.width=canvas.width;slice.height=Math.min(pagePx,canvas.height-y);slice.getContext('2d').drawImage(canvas,0,y,canvas.width,slice.height,0,0,canvas.width,slice.height);if(n++)pdf.addPage();pdf.addImage(slice.toDataURL('image/png'),'PNG',10,10,drawW,slice.height/ratio);pdf.addImage(mark,'PNG',25,130,160,42);pdf.setFontSize(8);pdf.setTextColor(140);pdf.text('RAINWISE / '+n,190,292,{align:'right'})}pdf.save('深雨知路_'+r.event.slice(0,40)+'.pdf')}finally{host.remove()}}
document.addEventListener('click',e=>{const b=e.target.closest('[data-v2="export"],[data-v2="export-record"],[data-v5="report"]');if(!b)return;e.preventDefault();e.stopImmediatePropagation();vDraft();v10ExportDialog(b.dataset.v2==='export-record'?vRecord(b.dataset.value):null,b.dataset.v5==='report'?b.dataset.value:'出行报告')},true);
document.addEventListener('submit',e=>{if(vFormId(e.target)!=='v10-export')return;e.preventDefault();const chosen=Object.fromEntries(new FormData(e.target)),s=vSnapshot(vExportRecord),parts=vExportParts(s,chosen);if(!EXPORT_FIELDS.some(([id])=>chosen[id]))return toast('请选择至少一项内容');V10.report={event:chosen.event,chosen,s,parts,exported:new Date().toISOString()};vDialog('报告预览',`<div class="v10reportpreview">${v10ReportHtml(V10.report)}</div><button class="primary" data-v10="download-report">确认导出 ${esc(chosen.format.toUpperCase())}</button><button data-v10="reselect">重新选择内容</button>`)});
document.addEventListener('click',async e=>{const b=e.target.closest('[data-v10]');if(!b)return;vDraft();const a=b.dataset.v10,v=b.dataset.value;if(a==='view'){V10.view=v;vRender()}if(a==='point-origin'||a==='point-destination'){if(a==='point-origin')V2.origin=v;else V2.destination=v;V2.page='dashboard';vRender()}if(a==='copy-source'){try{await navigator.clipboard.writeText(v);toast('直接下载链接已复制')}catch{toast('复制不可用，可从下方文本框复制链接')}}if(a==='reselect')return v10ExportDialog(vExportRecord,V10.exportLabel);if(a==='download-report'){const r=V10.report;if(!r)return;r.exported=new Date().toISOString();try{if(r.chosen.format==='pdf')await v10Pdf(r);else if(r.chosen.format==='png')await vPng([{title:r.event,text:'导出 '+dateText(r.exported)},...r.parts],r.s,r.chosen);else if(r.chosen.format==='html')download('深雨知路_报告.html','<!doctype html><meta charset="utf-8"><title>'+esc(r.event)+'</title>'+v10ReportHtml(r),'text/html');else download('深雨知路_报告.txt','深雨知路 · RAINWISE\n事件 '+r.event+'\n回放／查询 '+(r.s.mode==='history'?r.s.at:r.s.created)+'\n导出 '+dateText(r.exported)+'\n\n'+r.parts.map(p=>p.title+'\n'+p.text).join('\n\n'));toast('报告已按所选内容导出')}catch(err){toast(err.message||'PDF导出失败，可选择HTML后打印为PDF')}}});
vRender();

function v10NewsIntersections(){if(!V9.active||V10.view!=='rebuild'||!V2.at.startsWith('2023-09-08'))return [];const pairs=[['SZ-E009','嘉宾路','建设路'],['SZ-E010','爱国路','文锦中路']];return pairs.map(([id,A,B])=>{const e=D.events.find(e=>e.record_id===id),a=R10.roads.filter(r=>r.name===A).flatMap(r=>r.coordinates),b=R10.roads.filter(r=>r.name===B).flatMap(r=>r.coordinates),keys=new Set(b.map(c=>c.join(','))),point=a.find(c=>keys.has(c.join(',')));return e?{event:e,point}:null}).filter(Boolean)}
const v10RiskLayerBase=v10RiskLayers;v10RiskLayers=function(map,L){v10RiskLayerBase(map,L);v10NewsIntersections().forEach(({event:e,point})=>{if(point)L.circleMarker([point[1],point[0]],{radius:10,color:'#fff',weight:2,fillColor:'#d39a52',fillOpacity:.9,bubblingMouseEvents:false}).bindTooltip(esc(e.place_text)+'：新闻记载当天积水，具体时刻未明；事后重建').on('click',()=>vDialog('历史重建线索',`<p>${typeof v17ExplainText==='function'?v17ExplainText(e.summary):esc(e.summary)}</p><p>新闻记载9月8日情况，但没有精确时刻，不能证明选定分钟现场状态。</p>${v9AsOfLink(e)}<p>点位为当前公开道路交叉点参考。</p>`)).addTo(map)})};
const v10PlaceDetailBase=v5PlaceDetail;v5PlaceDetail=function(){return v10PlaceDetailBase()+(v10NewsIntersections().length?`<section class="card" style="margin-top:20px"><h2>当天新闻重建线索 · 非此刻实测</h2>${v10NewsIntersections().map(({event:e,point})=>`<div class="listitem"><b>${esc(e.place_text)}</b><p>${typeof v17ExplainText==='function'?v17ExplainText(e.summary):esc(e.summary)}</p><small>${point?'可显示公开道路交叉点参考':'没有可靠定位，暂不落点'} · 发生具体时刻未明</small><br>${v9AsOfLink(e)}</div>`).join('')}</section>`:'')};
const v10PartsBase=vExportParts;vExportParts=function(s,chosen){const parts=v10PartsBase(s,chosen),item=parts.find(p=>p.title==='方案对比');if(item&&chosen.plans)item.text+='\n\n'+s.plans.filter(p=>p.segments?.length).map(p=>'上车 '+p.boarding+'；下车 '+p.alighting+'\n'+p.segments.map(g=>g.line+'号线 '+g.from+' → '+g.to+'（'+g.stops+'站）'+(g.closed?'；当时公告涉及停运':'；运营状态需核验')).join('\n')+'\n到达 '+p.arrivalText+'\n'+p.estimateBasis).join('\n\n');return parts};
vRender();

const v10PartsFinal=vExportParts;vExportParts=function(s,c){const parts=v10PartsFinal(s,c),j=parts.find(x=>x.title==='行程与时间');if(j&&s.planned)j.text+='\n计划出发 '+dateText(s.planned)+'；资料截止时刻独立保留';return parts};
