const v10SnapshotBase=vSnapshot;vSnapshot=function(p){const s=v10SnapshotBase(p);return {...s,query_created_at:p?.created||vFocus()?.created||s.created}};
const v10ReportHtmlBase=v10ReportHtml;v10ReportHtml=function(r){return v10ReportHtmlBase({...r,s:{...r.s,created:r.s.query_created_at||r.s.created}})};
const v10FinalPartsBase=vExportParts;vExportParts=function(s,c){const parts=v10FinalPartsBase(s,c),p=parts.find(x=>x.title==='方案对比');if(p)p.text+='\n\n'+s.plans.flatMap(p=>(p.segments||[]).filter(g=>g.closure).map(g=>'停运依据 '+g.closure.source_published_at+'\n'+g.closure.source_url)).join('\n');return parts};
vMapSvgSnapshot=function(s){const lines=s.plans.flatMap(p=>p.segments?.length?p.segments.map(g=>({coordinates:g.coordinates,color:g.closed?'#c95454':VC[s.plans.indexOf(p)%VC.length]})):p.geometry?[{coordinates:p.geometry.coordinates,color:VC[s.plans.indexOf(p)%VC.length]}]:[]),pts=lines.flatMap(l=>l.coordinates);if(!pts.length)return '<p>没有已取得轨迹，不用直线代替路径。</p>';const xs=pts.map(c=>c[0]),ys=pts.map(c=>c[1]),minx=Math.min(...xs),maxx=Math.max(...xs),miny=Math.min(...ys),maxy=Math.max(...ys),dx=maxx-minx||.01,dy=maxy-miny||.01,cx=Math.cos((maxy+miny)*Math.PI/360),scale=Math.min(630/(dx*cx),210/dy),ox=(700-dx*cx*scale)/2,oy=(260-dy*scale)/2;return `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 700 300"><rect width="700" height="300" fill="#f3f7f8"/>${lines.map(l=>`<polyline points="${l.coordinates.map(c=>(ox+(c[0]-minx)*cx*scale)+','+(260-oy-(c[1]-miny)*scale)).join(' ')}" fill="none" stroke="${l.color}" stroke-width="4"/>`).join('')}<text x="20" y="282" fill="#7c939a" font-size="11">当前轨迹参考 · 非灾时通行保证 · © OpenStreetMap contributors · ODbL</text></svg>`};
vRender();
const v10TermsBase=vTerms;vTerms=function(p){const original=v10TermsBase(p);return [...new Set(original.flatMap(t=>[t,v10Normalize(t),vResolve(t)?.name]).filter(t=>t&&t.length>=2))]};
vRender();
